const RC=META.parts.length+1, QZ=RC+1, LS=RC+2, OUT=RC+3;

/* ---------- drawing helpers for this lesson (prefixed AU_ so they never clash with engine globals) ---------- */
const AU_F='font-family="Nunito Sans, sans-serif"';
const AU_MUT='#5C6577', AU_GR='#ADB5BD';
const AU_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${AU_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.op?` fill-opacity="${o.op}"`:''}>${t}</text>`;
const AU_L=(x1,y1,x2,y2,col=AU_MUT,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const AU_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??12}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.ex||''}/>`;
const AU_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return AU_L(x1,y1,(x2-h*.6*Math.cos(a)).toFixed(1),(y2-h*.6*Math.sin(a)).toFixed(1),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const AU_X=(x,y,s,col,w=5)=>AU_L(x-s,y-s,x+s,y+s,col,w)+AU_L(x-s,y+s,x+s,y-s,col,w);
const AU_lbl=(x,y,w,h,t,col,fill,fs=22)=>AU_box(x,y,w,h,{r:8,fill,st:col})+AU_T(x+w/2,y+h/2+fs*.36,t,{fs,fw:800,a:'middle',fill:col});
const AU_sub=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
/* computed data */
const AU_bits=(v,n=11)=>Array.from({length:n},(_,i)=>(v>>(n-1-i))&1);      // MSB first
const AU_A=AU_bits(0x123), AU_B=AU_bits(0x121);                            // 0,0,1,0,0,1,0,0,0,1,1 and …0,0,1
const AU_LIN_TAU=1/19200, AU_T_NOM=(34+10*(8+1))*AU_LIN_TAU*1000;          // 6.458 ms
const AU_FD=[[9,12],[10,16],[11,20],[12,24],[13,32],[14,48],[15,64]];        // CAN FD DLC codes -> data bytes
/* CAN-H and CAN-L over a bit stream: recessive 1 = 2.5 V on both, dominant 0 = 3.5 V and 1.5 V */
const AU_canWave=(bits,x0,w,yv,wire)=>{let p=[];bits.forEach((b,i)=>{const v=b?2.5:(wire==='H'?3.5:1.5),y=yv(v).toFixed(1);p.push(`${(x0+i*w).toFixed(1)},${y}`,`${(x0+(i+1)*w).toFixed(1)},${y}`)});return `<polyline points="${p.join(' ')}" fill="none" stroke="${wire==='H'?ORG:BLU}" stroke-width="5" stroke-linejoin="round"/>`};
/* one row of bit cells */
const AU_row=(bits,x0,y,w,col,o={})=>bits.map((b,i)=>b===null?'':AU_box(x0+i*w+2,y,w-4,40,{r:6,fill:o.hl&&o.hl(i)?o.hlFill:'#FFFFFF',st:o.hl&&o.hl(i)?o.hlCol:col})+AU_T(x0+i*w+w/2,y+29,b,{fs:24,fw:800,a:'middle',fill:o.hl&&o.hl(i)?o.hlCol:col})).join('');

